              <div className="bg-gray-800 rounded-xl p-4"><div className="text-yellow-400 font-semibold mb-2">❓ Common Investor Questions</div><div className="space-y-3">{result.dueDiligencePrep.common_questions?.slice(0,5).map((q: any, i: number) => <div key={i}><div className="text-white text-sm font-medium">{q.question}</div><div className="text-gray-400 text-xs mt-1">{q.answer_framework}</div></div>)}</div></div>
