// --- v9.62 AI Brand Audit & Identity Analyzer ---
const BRAND_MATURITY_COLOR: Record<string,string> = { 'Nascent':'bg-red-700','Developing':'bg-orange-700','Established':'bg-yellow-700','Strong':'bg-blue-700','Iconic':'bg-purple-700' };
